theorem quaternionic_plane (S : CandidateSystem) :
    Module.finrank ℝ S.H = 8 ∧ Module.finrank ℝ ℍ[ℝ] = 4 ∧
      @Module.finrank ℍ[ℝ] S.H _ _ S.quatModule = 2

